-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     'Component Item' AS \"Record Type\",     im.ITEM AS \"Item ID\",     im.ITEM_DESC AS \"Item Description\",     im.PACK_IND AS \"Pack Indicator\",     im.DEPT AS \"Department Number\",     im.CLASS AS \"Class Number\",     im.SUBCLASS AS \"Subclass Number\",     im.STATUS AS \"Item Status\",     r.PRIMARY_PACK_NO AS \"Primary Pack Number\",     r.PRIMARY_PACK_QTY AS \"Primary Pack Quantity\",     NULL AS \"Pack Item Description\",     isc.SUPPLIER AS \"Supplier ID\",     s.SUP_NAME AS \"Supplier Name\",     isc.ORIGIN_COUNTRY AS \"Origin Country\",     isc.DIM_OBJECT AS \"Dimension Object\",     isc.WEIGHT AS \"Gross Weight\",     isc.NET_WEIGHT AS \"Net Weight\",     isc.TARE_WEIGHT AS \"Tare Weight\",     isc.TARE_TYPE AS \"Tare Type\",     isc.WEIGHT_UOM AS \"Weight Unit of Measure\",     CASE WHEN isc.WEIGHT = isc.NET_WEIGHT THEN 'Gross = Net' WHEN isc.WEIGHT &lt; isc.NET_WEIGHT THEN 'Gross &lt; Net' END AS \"Weight Discrepancy\",     r.LOCATION AS \"Location ID\",     r.LOC_TYPE AS \"Location Type\",     r.REPL_METHOD AS \"Replenishment Method\",     r.STOCK_CAT AS \"Stock Category\",     r.STATUS AS \"Replenishment Status\" FROM rds_wv_repl_item_loc r INNER JOIN rds_wv_item_master im ON im.ITEM = r.ITEM INNER JOIN rds_wv_item_supp_country_dim isc ON isc.ITEM = r.ITEM AND isc.DIM_OBJECT = 'CA' INNER JOIN rds_wv_sups s ON s.SUPPLIER = isc.SUPPLIER  UNION ALL

